namespace LoomTerminal.Core.Tests.Conformance;

public sealed class ScenarioConformanceTests
{
    private static string ScenarioFolder => Path.Combine(AppContext.BaseDirectory, "Conformance", "Fixtures", "scenarios");

    public static IEnumerable<object[]> ScenarioNames() =>
        Directory.GetFiles(ScenarioFolder, "*.input")
            .Select(path => Path.GetFileNameWithoutExtension(path))
            .Order(StringComparer.Ordinal)
            .Select(name => new object[] { name });

    // The expected JSON is generated by tools/xterm-oracle with xterm.js itself.
    [Theory]
    [MemberData(nameof(ScenarioNames))]
    public void Scenario_matches_xterm_js(string name)
    {
        string input = File.ReadAllText(Path.Combine(ScenarioFolder, name + ".input"));
        string expected = ScreenSnapshotJsonContext.Normalize(File.ReadAllText(Path.Combine(ScenarioFolder, name + ".json")));

        ScreenSnapshot actual = FixtureReader.Replay(FixtureReader.ReadInput(input));

        Assert.Equal(expected, ScreenSnapshotJsonContext.ToJson(actual));
    }
}
